import{K as r,a as i,c as d,b as t,k as l,q as c,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Office 文件保存、格式转换与版本恢复","description":"保存与另存副本、AutoSave 和自动恢复的区别，Office 文件格式、PDF 导出、云端历史版本、兼容性和交付检查。","frontmatter":{"title":"Office 文件保存、格式转换与版本恢复","description":"保存与另存副本、AutoSave 和自动恢复的区别，Office 文件格式、PDF 导出、云端历史版本、兼容性和交付检查。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · 入门与通用操作","summary":"保存与另存副本、AutoSave 和自动恢复的区别，Office 文件格式、PDF 导出、云端历史版本、兼容性和交付检查。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Office 版本选择、安装与工作环境","link":"/tools/office/start/setup"},"next":{"text":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Office 版本选择、安装与工作环境","link":"/tools/office/start/setup"},"next":{"text":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts"}},"headers":[],"relativePath":"tools/office/start/files.md","filePath":"tools/office/start/files.md"}'),n={name:"tools/office/start/files.md"},k=Object.assign(n,{setup(h){const o={path:"/tools/office/start/files",app:"Word",title:"保存副本后导出可交付 PDF",steps:[{tab:"文件",command:"另存为",setting:"文件名：报告-练习副本.docx；位置：工作文件夹",anchor:"walkthrough-1"},{tab:"文件",command:"导出",setting:"创建 PDF/XPS；范围：全部页面",anchor:"walkthrough-2"},{tab:"文件",command:"打开",setting:"打开刚导出的 PDF；逐页预览",anchor:"walkthrough-3",app:"PDF 阅读器"}]};return(f,e)=>{const a=r("OfficeGuide");return i(),d("div",null,[e[0]||(e[0]=t("h1",{id:"office-文件保存、格式转换与版本恢复",tabindex:"-1"},[l("Office 文件保存、格式转换与版本恢复 "),t("a",{class:"header-anchor",href:"#office-文件保存、格式转换与版本恢复","aria-label":'Permalink to "Office 文件保存、格式转换与版本恢复"'},"​")],-1)),e[1]||(e[1]=t("p",null,"文件管理的目标是知道“当前编辑哪份文件、保存在何处、谁能访问、出错如何回到上一个状态”。只看到标题栏写着“已保存”，还不足以确认共享和交付完成。",-1)),c(a,{guide:o}),e[2]||(e[2]=s('<h2 id="save" tabindex="-1">保存、另存为与另存副本 <a class="header-anchor" href="#save" aria-label="Permalink to &quot;保存、另存为与另存副本 {#save}&quot;">​</a></h2><p>首次保存时选定文件夹，使用包含项目、内容和日期的名字，例如 <code>培训计划_2026-11-01_草稿.docx</code>。继续编辑同一份工作文件时使用“保存”；要基于模板做另一份材料，先“另存为”或“保存副本”，再开始修改。</p><p>启用 AutoSave 的云端文件可能即时保存改动，所以“改完后关闭并选择不保存”不是可靠的试算方式。需要测试不同方案时，先建立副本，或复制工作表到独立的试算文件。</p><p>Microsoft 365 中 AutoSave 通常依赖文件存于受支持的 OneDrive 或 SharePoint 位置、文件格式和相应条件。它与程序崩溃后尝试提供恢复内容的“自动恢复”不同；后者也不保证保留每次击键。<a href="https://support.microsoft.com/en-us/office/collab-files/what-is-autosave" target="_blank" rel="noopener noreferrer">微软 AutoSave 说明</a></p><h2 id="formats" tabindex="-1">选择文件格式 <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;选择文件格式 {#formats}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>格式</th><th>需要留意</th></tr></thead><tbody><tr><td>Word 可继续编辑</td><td><code>.docx</code></td><td>不保存 VBA 宏</td></tr><tr><td>Excel 可继续计算</td><td><code>.xlsx</code></td><td>不保存 VBA 宏</td></tr><tr><td>PowerPoint 可继续编辑</td><td><code>.pptx</code></td><td>放映和编辑都可以使用</td></tr><tr><td>含宏的 Word / Excel / PPT</td><td><code>.docm</code> / <code>.xlsm</code> / <code>.pptm</code></td><td>仅在确有需要且来源可信时使用</td></tr><tr><td>可重复使用的普通模板</td><td><code>.dotx</code> / <code>.xltx</code> / <code>.potx</code></td><td>用模板新建实例，避免修改模板本体</td></tr><tr><td>保留页面呈现的交付版</td><td><code>.pdf</code></td><td>检查页数、字体、链接和批注输出设置</td></tr><tr><td>纯数据交换</td><td><code>.csv</code></td><td>没有多工作表、格式、图表和可继续计算的公式</td></tr></tbody></table><p>CSV 是按字段分隔的文本，保存工作簿为 CSV 通常只导出当前工作表的值。含前导零的编号、长数字和日期可能在重新打开时被自动识别；应通过 Excel“数据 → 从文本/CSV”指定类型，而不是反复双击试运气。不要把唯一的 Excel 工作文件覆盖成 CSV。</p><h2 id="recover" tabindex="-1">恢复错误修改 <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;恢复错误修改 {#recover}&quot;">​</a></h2><p>刚刚发生的误操作先用撤销；已经保存的本地文件还可能依赖系统备份。对支持版本历史的云端文件，可从文件标题菜单或“文件 → 信息”进入“版本历史记录”，查看旧版本，确认内容和时间，再选择恢复或保存副本。菜单位置依应用和平台不同。</p><p>当程序意外关闭时，重新启动后检查“文档恢复”窗格。Word、Excel 桌面版还可能在“文件 → 信息 → 管理文档/工作簿”提供恢复未保存内容入口。找回后立即另存到明确位置，并核对结尾几段或最后几行，不要只确认文件能打开。</p><p>同步不是完整备份策略：误删、覆盖和权限变更可能被同步。重要里程碑保留独立交付版本；需要长期恢复能力时，确认组织的版本保留、回收站和备份政策。</p><h2 id="pdf" tabindex="-1">导出 PDF 的完整步骤 <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;导出 PDF 的完整步骤 {#pdf}&quot;">​</a></h2><ol><li>保存可编辑源文件。</li><li>在打印预览确认页面范围、纸张、方向和缩放；Excel 额外检查打印区域。</li><li>通过“文件 → 导出”或“另存为”选择 PDF，检查导出选项。</li><li>Word 确认是否包含修订标记；PowerPoint 确认导出幻灯片、讲义还是备注页。</li><li>打开生成的 PDF，实际翻到首页、跨页表格、图片页和末页。</li><li>将 PDF 与对应源文件放在同一交付目录，文件名体现相同版本。</li></ol><p>PDF 有助于稳定呈现，但不能代替权限管理，也不自动意味着内容不可复制。含敏感信息的文件应先清理源内容和文档属性，而不是仅在上面盖一个白色图形。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>新建一份文档，保存为 <code>原稿.docx</code>，再保存副本 <code>修改稿.docx</code>。只在副本增加“第二版本”一行，关闭后分别打开，确认原稿未变化。再从副本导出 PDF，验证内容、页数与文件位置。</p><p>若使用云端文件，再做一次版本历史查看练习；只查看或把旧版本另存，不在团队正在编辑的正式文件上试验恢复操作。</p><h2 id="walkthrough" tabindex="-1">图示跟做：保存副本后导出可交付 PDF <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：保存副本后导出可交付 PDF {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先留下可回退的源文件 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先留下可回退的源文件 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：文件 → 另存为。</strong></p><p>打开练习文档，选择“文件 → 另存为”，云端文件也可能显示“保存副本”。确认文件名和目录后保存，再看标题栏是否已切到副本。只改窗口中的名称而没有完成保存，不能算已经备份；关闭并重新打开副本是最直接的检查。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：检查导出选项 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：检查导出选项 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：文件 → 导出。</strong></p><p>在“文件 → 导出”中创建 PDF/XPS，选择目标文件夹。打开选项，确认导出全部页面还是指定范围，以及是否包含标记。带修订的审阅稿和不显示标记的阅读稿用途不同，先明确交付目的再导出。源文档继续保留 docx 格式。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：从接收者角度复核 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：从接收者角度复核 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 打开。</strong></p><p>在 PDF 阅读器中打开刚导出的文件，检查最后一页、横向页、表格右边缘和目录跳转。放大到能读清正文的比例，核对中文字体与符号。发现错页应返回源文件修正并重新导出，避免只在 PDF 上补丁式修改而让源文档与交付版分叉。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>自动保存与自动恢复不是同一件事。云端文件要检查同步状态和版本历史；本地文件不能仅凭看见“保存”按钮就假定已进入云端备份。</p>',30))])}}});export{u as __pageData,k as default};
